+    "/Logo Do /Logo Do",
+  );
+
+  assert(result.ok);
+  expect(
+    result.value.warnings.map(({ code, offset }) => [code, offset]),
+  ).toEqual([
+    ["FORM_XOBJECT_CYCLE", 6],
+    ["FORM_XOBJECT_CYCLE", 15],
